const json = $input.first().json;

// Gemini / OpenAI / réponse directe
const raw = json.candidates?.[0]?.content?.parts?.[0]?.text
  ?? json.choices?.[0]?.message?.content
  ?? json.content
  ?? json.text;

if (!raw) {
  throw new Error("Réponse LLM introuvable. Structure reçue : " + JSON.stringify(Object.keys(json)));
}

// Fonction pour extraire le JSON le plus complet possible
function extractJSON(str) {
  const start = str.indexOf('{');
  if (start === -1) return null;

  let stack = [];
  let end = start;
  for (let i = start; i < str.length; i++) {
    const char = str[i];
    if (char === '{') stack.push('{');
    else if (char === '}') stack.pop();

    if (stack.length === 0) {
      end = i + 1;
      break;
    }
  }

  return str.substring(start, end);
}

let jsonString = extractJSON(raw);

if (!jsonString) {
  throw new Error("Aucun JSON valide trouvé dans la réponse : " + raw);
}

// Nettoyer les retours à la ligne et tabulations
jsonString = jsonString.replace(/\r/g, '')
                       .replace(/\t/g, ' ')
                       .replace(/\n/g, ' ');

// Parser en JSON
let parsed;
try {
  parsed = JSON.parse(jsonString);
} catch(err) {
  const snippet = jsonString.slice(0, 500);
  throw new Error(`Erreur JSON.parse: ${err.message}\nSnippet: ${snippet}\nRéponse brute: ${raw}`);
}

// Retourner les données du CV
return [{ json: { cvData: parsed } }];

const json = $input.first().json;

// Récupérer le texte brut de la réponse LLM
const raw = json.choices?.[0]?.message?.content
  ?? json.candidates?.[0]?.content?.parts?.[0]?.text
  ?? json.content
  ?? json.text;

if (!raw) {
  throw new Error("Réponse LLM introuvable. Structure reçue : " + JSON.stringify(Object.keys(json)));
}

// Nettoyer la chaîne de caractères : retours chariots, tabulations
let cleaned = raw.replace(/\r/g, '').replace(/\t/g, ' ').trim();

// Extraire à partir de la première accolade ouvrante
const firstBrace = cleaned.indexOf('{');
if (firstBrace === -1) {
  throw new Error("Aucune accolade ouvrante trouvée dans la réponse : " + raw);
}

let jsonString = cleaned.substring(firstBrace);

// Parser en JSON avec try/catch
let parsed;
try {
  parsed = JSON.parse(jsonString);
} catch (err) {
  // Si erreur, afficher les 500 premiers caractères pour debug
  const snippet = jsonString.slice(0, 500);
  throw new Error(`Erreur JSON.parse: ${err.message}\nSnippet: ${snippet}\nRéponse brute: ${raw}`);
}

// Récupérer nom et id depuis le nœud Search
const fileName = $('Search files and folders').item.json.name;
const fileId   = $('Search files and folders').item.json.id;

// Retourner un objet stable
return [{
  json: {
    jobPostData: parsed,
    fileName,
    fileId
  }
}];

const item = $input.first().json;

// Récupérer métadonnées depuis le nœud précédent
const meta = $('Code in JavaScript2').item.json;
const fileId        = meta.fileId ?? '';
const fileName      = meta.fileName ?? '';
const intitulePoste = meta.intitulePoste ?? '';

// Extraire strictement le JSON de la réponse LLM
const raw = item.choices?.[0]?.message?.content
  ?? item.content
  ?? item.text;

if (!raw) {
  throw new Error("Réponse LLM introuvable. Structure reçue : " + JSON.stringify(Object.keys(item)));
}

const start = raw.indexOf('{');
const end   = raw.lastIndexOf('}') + 1;

if (start === -1 || end === -1) {
  throw new Error("Aucun JSON trouvé dans la réponse : " + raw);
}

const jsonString = raw.substring(start, end).replace(/\n/g, '');

// Parser en JSON
let result;
try {
  result = JSON.parse(jsonString);
} catch(err) {
  throw new Error("Erreur JSON.parse: " + err.message + "\nRéponse brute: " + raw);
}

return [{
  json: {
    fileId,
    fileName,
    jobTitle: intitulePoste,
    scoreGlobal: result.scoreGlobal,
    status: result.scoreGlobal >= 70 ? 'MATCH' : 'NO_MATCH',
    detail: result,
    createdAt: new Date().toISOString()
  }
}];

