const inputItem = $input.first().json;

const cvData      = inputItem.cvData      ?? {};
const jobPostData = inputItem.jobPostData ?? {};
const fileId      = inputItem.fileId      ?? '';
const fileName    = inputItem.fileName    ?? '';
const intitulePoste = jobPostData.intitulePoste ?? '';

if (!cvData.nom && !cvData.competencesTechniques) {
  throw new Error("cvData vide ! Structure reçue : " + JSON.stringify(Object.keys(inputItem)));
}

const body = JSON.stringify({
  model: "openai/gpt-4o-mini",
  messages: [{
    role: "user",
    content: `Tu es un recruteur expert et bienveillant. Compare ce CV avec cette fiche de poste.
Retourne STRICTEMENT le JSON ci-dessous, sans texte avant ni après.

RÈGLES DE SCORING (très important) :
- Évalue chaque critère sur une échelle PROPORTIONNELLE, pas binaire.
- Un candidat qui couvre 60% des compétences techniques requises obtient ~60% du score max (pas 0).
- Pour l'expérience : si le poste demande 8 ans et le candidat en a 7, donne ~85% du score (pas 0).
- Pour la formation : évalue d'abord le niveau (Bac+5 = base solide = 10/15 minimum), les certifications sont un bonus.
- Pour les soft skills : extrait-les IMPLICITEMENT depuis les expériences et le profil, pas seulement les mots-clés listés.
- Pour les langues : si la fiche ne précise pas de langue, donne le score max (5/5). Si elle en précise, vérifie le CV.
- Ne pénalise JAMAIS un critère à 0 sauf si le candidat est totalement hors domaine.

PONDÉRATION :
- competencesTechniques : 40% (score sur 40)
- experience            : 30% (score sur 30)
- formation             : 15% (score sur 15)
- softSkills            : 10% (score sur 10)
- langues               : 5%  (score sur 5)
- scoreGlobal = somme des 5 scores (sur 100)

FORMAT JSON attendu :
{
  "scoreGlobal": 0,
  "competencesTechniques": { "score": 0, "detail": "..." },
  "experience": { "score": 0, "detail": "..." },
  "formation": { "score": 0, "detail": "..." },
  "softSkills": { "score": 0, "detail": "..." },
  "langues": { "score": 0, "detail": "..." },
  "pointsForts": ["..."],
  "pointsFaibles": ["..."],
  "resume": "...",
  "recommandation": "retenir ou ecarter"
}

Contraintes :
- "detail" : 2 lignes max, cite des exemples concrets du CV.
- "resume" : 3 lignes max.
- JSON valide strictement, aucun texte supplémentaire.

PROFIL CV:
${JSON.stringify(cvData)}

FICHE DE POSTE:
${JSON.stringify(jobPostData)}`
  }]
});

return [{ json: { 
  body,
  fileId,
  fileName,
  intitulePoste
} }];

